WoWFA_En[633] = "Heals a friendly target for an amount equal to $s2% your maximum health.$?a387791[\n\nGrants the target $387792s1% increased armor for $387792d.][]\n\nCannot be used on a target with Forbearance. Causes Forbearance for $25771d."
WoWFA_Data[633] = "یک هدف دوستانه را به‌اندازهٔ 100% از حداکثر سلامتی شما شفا می‌دهد.$?a387791[\n\nبرای 8 ثانیه، زره هدف را 30% افزایش می‌دهد.][]\n\nنمی‌توان روی هدفی که Forbearance دارد استفاده کرد. به‌مدت 30 ثانیه باعث Forbearance می‌شود."
WoWFA_En[1022] = "Blesses a party or raid member, granting immunity to Physical damage and harmful effects for $d.\n\nCannot be used on a target with Forbearance. Causes Forbearance for $25771d.$?c2[\n\nShares a cooldown with Blessing of Spellwarding.][]"
WoWFA_Data[1022] = "به یک عضو پارتی یا رید Blessing می‌دهد و برای 10 ثانیه او را در برابر آسیب Physical و اثرات مضر ایمن می‌کند.\n\nنمی‌توان روی هدفی که Forbearance دارد استفاده کرد. به مدت 30 ثانیه باعث Forbearance می‌شود.$?c2[\n\nبا Blessing of Spellwarding کول‌داون مشترک دارد.][]"
WoWFA_En[1044] = "Blesses a party or raid member, granting immunity to movement impairing effects $?s199325[and increasing movement speed by $199325m1% ][]for $d."
WoWFA_Data[1044] = "به یک عضو پارتی یا رید Blessing می‌دهد و برای 8 ثانیه او را در برابر اثرات مختل‌کنندهٔ حرکت ایمن می‌کند$?s199325[ و سرعت حرکتش را 30% افزایش می‌دهد][]."
WoWFA_Data[6940] = "به یک عضو پارتی یا رید Blessing می‌دهد و آسیب دریافتی او را 30% کاهش می‌دهد، اما شما 100% از آسیب پیشگیری‌شده را متحمل می‌شوید.\n\nبه مدت 12 ثانیه ادامه دارد یا تا زمانی که آسیب منتقل‌شده سلامتی شما را به کمتر از 20% برساند."
WoWFA_Data[10326] = "قدرت Light یک هدف Undead، Aberration یا Demon را وادار می‌کند تا حداکثر 40 ثانیه فرار کند. آسیب ممکن است اثر را بشکند. موجودات ضعیف‌تر ممکن است نابود شوند. در هر لحظه فقط یک هدف را می‌توان برگرداند."
WoWFA_En[20473] = "Triggers a burst of Light on the target, dealing $25912s1 Holy damage to an enemy, or $25914s1 healing to an ally.$?s272906[  Has an additional $272906s1% critical strike chance.][]\n\n|cFFFFFFFFGenerates $s2 Holy Power.\n"
WoWFA_Data[20473] = "انفجاری از Light را روی هدف ایجاد می‌کند و به دشمن $25912s1 آسیب Holy یا به متحد $25914s1 شفا وارد می‌کند.$?s272906[  شانس Critical Strike آن 10% بیشتر است.][]\n\n|cFFFFFFFFمقدار 1 Holy Power تولید می‌کند."
WoWFA_Data[31821] = "آورای انتخاب‌شده‌تان را برای 8 ثانیه تقویت می‌کند.\n\nDevotion Aura: کاهش آسیب به 12% افزایش می‌یابد.\n\nCrusader Aura: پاداش سرعت مانت به 60% افزایش می‌یابد.\n\nConcentration Aura: متحدان تحت تأثیر در برابر قطع و سایلنت مصون می‌شوند."
WoWFA_Data[31850] = "تمام آسیب دریافتی شما را به‌اندازهٔ 30% برای 12 ثانیه کاهش می‌دهد.\n\nتا زمانی که Ardent Defender فعال است، حملهٔ بعدی که در حالت عادی شما را می‌کشت، در عوض سلامتی‌تان را به 20% از حداکثر سلامتی‌تان می‌رساند."
WoWFA_En[31884] = "Call upon the Light to become an avatar of retribution, $?s53376&c2[causing Judgment to generate $53376s3 additional Holy Power, ]?s53376&c3[each Holy Power spent causing you to explode with Holy light for $326731s1 damage to nearby enemies, ][]increasing your damage, healing, and critical strike chance by $s2%$?s1253598[ and Haste by $s11%][] for $d.$?s1253598[\n\nEach Holy Power spent increases Haste by an additional $1253598s1%, up to $1253598s2%.][]"
WoWFA_Data[31884] = "برای تبدیل شدن به تجسم انتقام، Light را فرا می‌خوانید؛ $?s53376&c2[با این اثر Judgment مقدار 1 Holy Power اضافی تولید می‌کند، ]?s53376&c3[هر Holy Power مصرف‌شده باعث می‌شود با نور مقدس منفجر شوید و $326731s1 آسیب به دشمنان نزدیک وارد کنید، ][]آسیب، شفا و شانس Critical Strike شما را 20%$?s1253598[ و Haste را 3%][] به‌مدت 20 ثانیه افزایش می‌دهد.$?s1253598[\n\nهر Holy Power مصرف‌شده، Haste را 2% دیگر افزایش می‌دهد؛ تا سقف 20%.][]"
WoWFA_En[31935] = "Hurls your shield at an enemy target, dealing $s1 Holy damage, interrupting and silencing the non-Player target for $d, and then jumping to ${$x1-1} additional nearby enemies. $?a209389[\n\nShields you for $209388d, absorbing $209389s1% as much damage as it dealt.][]$?a378285[\n\nDeals $<dmg> additional damage to all enemies within $378286A1 yds of each target hit.][]\n"
WoWFA_Data[31935] = "سپر خود را به‌سوی هدف دشمن پرتاب می‌کنید و $s1 آسیب Holy وارد می‌کنید، هدف غیر بازیکن را برای 3 ثانیه قطع و سایلنت می‌کنید، سپس سپر به 2 دشمن نزدیک دیگر می‌جهد. $?a209389[\n\nبرای 8 ثانیه سپری به شما می‌دهد که به‌اندازهٔ 75% آسیب واردشده، آسیب جذب می‌کند.][]$?a378285[\n\nبه همهٔ دشمنان در فاصلهٔ 5 یاردی از هر هدف اصابت‌کرده، $<dmg> آسیب اضافی وارد می‌کند.][]"
WoWFA_En[53376] = "$?(c1|c2|c3)[][The duration of Avenging Wrath is increased by $s1%.]$?c1[Avenging Wrath and Avenging Crusader have $s1% increased duration.]?c2[Avenging Wrath and Sentinel cause Judgment to generate $s3 additional Holy Power,]?c3[Avenging Wrath and Crusade cause each Holy Power spent to explode with Holy light for $326731s1 damage to nearby enemies,][]$?(c2|c3)[ and have $s1% increased duration.][]"
WoWFA_Data[53376] = "$?(c1|c2|c3)[][مدت Avenging Wrath به‌اندازه 25% افزایش می‌یابد.]$?c1[مدت Avenging Wrath و Avenging Crusader 25% بیشتر می‌شود.]?c2[Avenging Wrath و Sentinel باعث می‌شوند Judgment مقدار 1 Holy Power اضافی تولید کند،]?c3[Avenging Wrath و Crusade باعث می‌شوند هر Holy Power مصرف‌شده با نور مقدس منفجر شود و $326731s1 آسیب به دشمنان نزدیک وارد کند،][]$?(c2|c3)[ و مدتشان 25% بیشتر می‌شود.][]"
WoWFA_En[53385] = "Unleashes a whirl of divine energy, dealing $?s405289[${$s1*1.05} Radiant][$s1 Holy] damage to all nearby enemies. \n\nDeals reduced damage beyond $s2 targets."
WoWFA_Data[53385] = "گردابی از انرژی الهی رها می‌کنید و به همه دشمنان نزدیک $?s405289[${$s1*1.05} آسیب Radiant][$s1 آسیب Holy] وارد می‌کنید. \n\nپس از 5 هدف، آسیب کاهش می‌یابد."
WoWFA_Data[53576] = "Holy Shockهای شما 10% شانس دارند جادوی بعدی شما را تقویت کنند:\n\nFlash of Light: شفا 200% افزایش می‌یابد و کست فوری می‌شود.\nJudgment: Greater Judgment از 150% آسیب اضافی واردشده توسط هدف جلوگیری می‌کند و 1 Holy Power اضافی تولید می‌کند."
WoWFA_En[53595] = "Hammers the current target for $53595sw1 Physical damage.$?s26573&s203785[\n\nHammer of the Righteous also causes a wave of light that hits all other targets within $88263A1 yds for $88263sw1 Holy damage.]?s26573[\n\nWhile you are standing in your Consecration, Hammer of the Righteous also causes a wave of light that hits all other targets within $88263A1 yds for $88263sw1 Holy damage.][]\n\n|cFFFFFFFFGenerates $s2 Holy Power."
WoWFA_Data[53595] = "به هدف فعلی $53595sw1 آسیب Physical وارد می‌کند.$?s26573&s203785[\n\nHammer of the Righteous همچنین موجی از نور ایجاد می‌کند که به همهٔ اهداف دیگر در فاصلهٔ 8 یاردی، $88263sw1 آسیب Holy وارد می‌کند.]?s26573[\n\nوقتی در Consecration خود ایستاده‌اید، Hammer of the Righteous همچنین موجی از نور ایجاد می‌کند که به همهٔ اهداف دیگر در فاصلهٔ 8 یاردی، $88263sw1 آسیب Holy وارد می‌کند.][]\n\n|cFFFFFFFFمقدار 1 Holy Power تولید می‌کند."
WoWFA_En[85043] = "When you avoid a melee attack or use $?S53595[Hammer of the Righteous]?S204019[Blessed Hammer][Crusader Strike], you have a $s1% chance to reset the remaining cooldown on Avenger's Shield$?S393022[ and increase your Strength by $393019s1% for $393019d.][.]"
WoWFA_Data[85043] = "وقتی از یک حملهٔ melee جاخالی می‌دهید یا از $?S53595[Hammer of the Righteous]?S204019[Blessed Hammer][Crusader Strike] استفاده می‌کنید، 15% شانس دارید کول‌داون باقی‌ماندهٔ Avenger's Shield را بازنشانی کنید$?S393022[ و Strength خود را برای 8 ثانیه به‌اندازهٔ 2% افزایش دهید.][.]"
WoWFA_En[85222] = "Unleashes Holy energy, healing up to $s2 injured allies within a $a1 yd radius around you for $s1."
WoWFA_Data[85222] = "انرژی Holy را آزاد می‌کند و تا 5 متحد زخمی را در شعاع 40 یاردی اطراف شما به‌اندازه $s1 شفا می‌دهد."
WoWFA_Data[86659] = "روح پادشاهان باستان شما را نیرومند می‌کند و تمام آسیب دریافتی‌تان را به‌اندازهٔ 50% برای 8 ثانیه کاهش می‌دهد."
WoWFA_Data[96231] = "کست اسپل را قطع می‌کند و از کست شدن هر اسپلی از آن school به‌مدت 5 ثانیه جلوگیری می‌کند."
WoWFA_En[114154] = "Reduces the cooldown of your Divine Shield, $?s184662[Shield of Vengeance, ][]$?s31850[Ardent Defender][Divine Protection], and Lay on Hands by $s1%."
WoWFA_Data[114154] = "کول‌داون Divine Shield، $?s184662[Shield of Vengeance، ][]$?s31850[Ardent Defender][Divine Protection] و Lay on Hands شما را 30% کاهش می‌دهد."
WoWFA_En[114165] = "Fires a beam of light that scatters to strike a clump of targets. \n\nIf the beam is aimed at an enemy target, it deals $114852s1 Holy damage and radiates ${$114852s2*$<healmod>} healing to 5 allies within $114852A2 yds.\n\nIf the beam is aimed at a friendly target, it heals for ${$114871s1*$<healmod>} and radiates $114871s2 Holy damage to 5 enemies within $114871A2 yds.\n\n|cFFFFFFFFGenerates $s2 Holy Power."
WoWFA_Data[114165] = "پرتوی از نور شلیک می‌کند که پراکنده شده و به گروهی از اهداف برخورد می‌کند. \n\nاگر پرتو به سمت یک هدف دشمن باشد، $114852s1 آسیب Holy وارد می‌کند و ${$114852s2*$<healmod>} شفا را به 5 متحد در فاصلهٔ 30 یارد می‌تاباند.\n\nاگر پرتو به سمت یک هدف دوستانه باشد، به میزان ${$114871s1*$<healmod>} شفا می‌دهد و $114871s2 آسیب Holy را به 5 دشمن در فاصلهٔ 30 یارد می‌تاباند.\n\n|cFFFFFFFF3 Holy Power تولید می‌کند."
WoWFA_Data[115750] = "درخشش خیره‌کننده‌ای را به همهٔ جهات می‌تاباند، دشمنان در فاصلهٔ 10 یارد را کور می‌کند و باعث می‌شود به‌مدت 6 ثانیه سرگردان و گیج شوند. آسیب ممکن است اثر را لغو کند."
WoWFA_Data[146956] = "حذف اثرات مضر با Divine Shield، به‌ازای هر اثر حذف‌شده شما را به‌اندازهٔ 10% شفا می‌دهد.  این شفا نمی‌تواند از 30% حداکثر سلامتی شما بیشتر شود.\n\nاکنون می‌توان Divine Shield را هنگام فعال بودن Forbearance کست کرد."
WoWFA_En[156322] = "Heals an ally for $s2 and an additional $o1 over $d.\n\nHealing increased by $?c1[$s3][$s4]% when cast on self."
WoWFA_Data[156322] = "یک متحد را به‌اندازه $s2 شفا می‌دهد و طی 16 ثانیه مقدار $o1 شفا اضافه می‌دهد.\n\nهنگام کست روی خود، شفا $?c1[25][35]% افزایش می‌یابد."
WoWFA_Data[156910] = "هدف دومی را به‌عنوان Beacon علامت‌گذاری می‌کنید تا اثرات Beacon of Light را تقلید کند. شفاهای شما اکنون هر دو Beacon شما را شفا می‌دهند، اما با اثربخشی 30% کمتر."
WoWFA_En[157047] = "When an ally with your Beacon of Light is damaged, they absorb the next $157128s1 damage, increasing by up to $s3% based on their current health. Lower health allies are shielded for more."
WoWFA_Data[157047] = "وقتی متحدی دارای Beacon of Light شما آسیب می‌بیند، $157128s1 آسیب بعدی را جذب می‌کند؛ این مقدار بر اساس سلامتی فعلی او تا $s3% افزایش می‌یابد. متحدان با سلامتی کمتر سپر بیشتری دریافت می‌کنند."
WoWFA_En[183416] = "While you are above $s3% health, $s1% of all damage taken by allies within $210372a1 yds is redirected to you, up to a maximum of $<maxAbsorb> every $s1 sec."
WoWFA_Data[183416] = "وقتی سلامتی شما بالاتر از 85% است، 5% از تمام آسیب دریافتی متحدان در فاصلهٔ 20 یارد به شما منتقل می‌شود؛ حداکثر تا $<maxAbsorb> در هر 5 ثانیه."
WoWFA_En[184575] = "$?s403826[Pierce enemies][Pierce an enemy] with a blade of light, dealing $s1 Holy damage$?s403826[ to your target and $404358s1 Holy damage to nearby enemies.][.]\n\n|cFFFFFFFFGenerates $s2 Holy Power.|r"
WoWFA_Data[184575] = "با تیغه‌ای از نور $?s403826[دشمنان][یک دشمن] را سوراخ می‌کنید و $s1 آسیب Holy$?s403826[ به هدف و $404358s1 آسیب Holy به دشمنان نزدیک وارد می‌کنید.][ وارد می‌کنید.]\n\n|cFFFFFFFF1 Holy Power تولید می‌کند.|r"
WoWFA_Data[190784] = "برای 3 ثانیه بر Charger خود سوار شوید و سرعت حرکت را 100% افزایش دهید. هنگام حضور در فضای بسته یا در مبارزه قابل استفاده است."
WoWFA_Data[196926] = "Holy Shock کول‌داون Judgment را 1.5 ثانیه و Crusader Strike کول‌داون Judgment را 1.5 ثانیه کاهش می‌دهد."
WoWFA_Data[197446] = "Mastery: Lightbringer اکنون شفاهای شما را بر اساس نزدیکی هدف به شما یا Beacon of Light شما، هرکدام که نزدیک‌تر باشد، افزایش می‌دهد."
WoWFA_En[199422] = "Allies are healed for $199423s1 when you cast Blessing of Protection or Blessing of Sacrifice on them."
WoWFA_Data[199422] = "هنگامی که Blessing of Protection یا Blessing of Sacrifice را روی متحدان کست می‌کنید، آن‌ها به میزان $199423s1 شفا می‌یابند."
WoWFA_Data[200025] = "یک Beacon of Light را به هدف و 4 متحد زخمی در فاصله 30 یارد اعمال می‌کنید و به‌مدت 9 ثانیه نگه می‌دارید.\n\nهمه متحدان تحت تأثیر به‌اندازه 10% از مقدار شفاهای دیگر شما شفا می‌یابند."
WoWFA_Data[200430] = "Aura Mastery همچنین تمام شفاهای دریافتی اعضای پارتی یا رید در فاصله 40 یارد را 10% افزایش می‌دهد."
WoWFA_Data[204018] = "عضو پارتی یا رید را برکت می‌دهد و برای 10 ثانیه در برابر آسیب جادویی و اثرات مضر مصونیت می‌بخشد.\n\nروی هدفی که Forbearance دارد قابل استفاده نیست. باعث Forbearance به‌مدت 30 ثانیه می‌شود.\n\nبا Blessing of Protection کول‌داون مشترک دارد."
WoWFA_En[204019] = "Throws a Blessed Hammer that spirals outward, dealing $204301s1 Holy damage to enemies and reducing the next damage they deal to you by $<shield>.\n\n|cFFFFFFFFGenerates $s2 Holy Power."
WoWFA_Data[204019] = "یک Blessed Hammer پرتاب می‌کند که به‌صورت مارپیچی به بیرون می‌رود، به دشمنان $204301s1 آسیب Holy وارد می‌کند و آسیب بعدی آن‌ها به شما را به‌اندازهٔ $<shield> کاهش می‌دهد.\n\n|cFFFFFFFFمقدار 1 Holy Power تولید می‌کند."
WoWFA_Data[204023] = "Judgment اکنون 2 شارژ دارد و Grand Crusader نیز کول‌داون Judgment را به‌اندازهٔ 3 ثانیه کاهش می‌دهد."
WoWFA_Data[204054] = "Consecration شما 15% بزرگ‌تر است و سرعت حرکت دشمنان درون آن 50% کاهش می‌یابد."
WoWFA_Data[204074] = "کول‌داون Avenging Wrath و Sentinel 50% کاهش و مدت آن‌ها 40% کاهش می‌یابد."
WoWFA_Data[204077] = "در طول Divine Shield، همهٔ اهداف در فاصلهٔ 15 یاردی تانت می‌شوند."
WoWFA_Data[209389] = "Avenger's Shield همچنین برای 8 ثانیه به شما سپر می‌دهد که به‌اندازهٔ 75% آسیب واردشده، آسیب جذب می‌کند؛ حداکثر تا 50% از حداکثر سلامتی شما."
WoWFA_Data[213644] = "یک هدف دوستانه را پاک‌سازی می‌کند و تمام اثرات Poison و Disease را از بین می‌برد."
WoWFA_Data[223817] = "توانایی‌هایی که Holy Power مصرف می‌کنند، 15% شانس دارند توانایی بعدیِ مصرف‌کنندهٔ Holy Power شما را رایگان کنند و آسیب و شفای آن را 15% افزایش دهند."
WoWFA_Data[230332] = "Divine Steed اکنون 2 شارژ دارد."
WoWFA_En[231644] = "Judgment deems the target unworthy, preventing the next $<shield> damage dealt by the target.\n"
WoWFA_Data[231644] = "Judgment هدف را ناشایست می‌داند و از وارد شدن $<shield> آسیب بعدیِ او جلوگیری می‌کند."
WoWFA_Data[231663] = "Judgment باعث می‌شود هدف از توانایی بعدی شما که Holy Power مصرف می‌کند، 20% آسیب بیشتری دریافت کند.\n\nاعمال چندباره می‌تواند روی هم انباشته شود."
WoWFA_Data[234299] = "کول‌داون Hammer of Justice به‌اندازهٔ 15 ثانیه کاهش می‌یابد."
WoWFA_En[255937] = "Lash out at your enemies, dealing $s1 Radiant damage to all enemies within $a1 yds in front of you, and applying $@spellname403695, burning the targets for an additional ${$403695s2*($403695d/$403695t+1)} damage over $403695d.\n\nDemon and Undead enemies are also stunned for $255941d.\n\n|cFFFFFFFFGenerates $s2 Holy Power."
WoWFA_Data[255937] = "به دشمنان خود حمله کنید و به همه دشمنان در فاصله 14 یاردی مقابل خود $s1 آسیب Radiant وارد کنید؛ همچنین Truth's Wake را اعمال کنید تا اهداف در طول 9 ثانیه، به‌اندازه ${$403695s2*($403695d/$403695t+1)} آسیب اضافی دریافت کنند.\n\nدشمنان Demon و Undead نیز برای 5 ثانیه استان می‌شوند.\n\n|cFFFFFFFF3 Holy Power تولید می‌کند."
