WoWFA_Data[305394] = "Blessing of Freedom سرعت حرکت را 30% افزایش می‌دهد و هنگامی که روی هدف دوستانه کست شود، شما نیز Blessing of Freedom می‌گیرید."
WoWFA_Data[315924] = "وقتی Word of Glory را روی فردی غیر از خودتان کست می‌کنید، شفای آن بر اساس سلامتی ازدست‌رفتهٔ هدف تا 100% افزایش می‌یابد."
