WoWFA_Data[403495] = "Judgment 10% آسیب بیشتری وارد می‌کند و سرعت حرکت شما را به‌اندازه 10% برای 5 ثانیه افزایش می‌دهد.\n\nاگر Greater Judgment را داشته باشید، Judgment دشمنان را به‌اندازه 30% برای 8 ثانیه کند می‌کند."
WoWFA_Data[403509] = "سرعت حملات خودکار به‌اندازه 20% افزایش می‌یابد."
WoWFA_En[403530] = "Successfully interrupting an enemy with Rebuke$?s31935[ or Avenger's Shield][] casts an extra $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?s137029[Holy Shock][Crusader Strike]."
WoWFA_Data[403530] = "قطع موفق کست دشمن با Rebuke$?s31935[ یا Avenger's Shield][]، یک $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?s137029[Holy Shock][Crusader Strike] اضافی کست می‌کند."
WoWFA_En[403664] = "$?s406646[Templar Strikes, ]?s404542[Crusading Strikes, ][Crusader Strike, ]Judgment and Blade of Justice deal $s2% increased damage."
WoWFA_Data[403664] = "$?s406646[Templar Strikes، ]?s404542[Crusading Strikes، ][Crusader Strike، ]Judgment و Blade of Justice، 10% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[403745] = "Blade of Justice اکنون 2 شارژ دارد."
WoWFA_En[403826] = "Blade of Justice now hits nearby enemies for $404358s1 Holy damage. \n\nDeals reduced damage beyond 5 targets."
WoWFA_Data[403826] = "Blade of Justice اکنون با وارد کردن $404358s1 آسیب Holy به دشمنان نزدیک ضربه می‌زند. \n\nپس از 5 هدف، آسیب کاهش می‌یابد."
WoWFA_En[404357] = "When your health is brought below $s1%, you instantly cast a free Word of Glory at $s2% effectiveness on yourself.\n\nCannot occur more than once every $proccooldown sec."
WoWFA_Data[404357] = "وقتی سلامتی شما به کمتر از 25% برسد، فوراً یک Word of Glory رایگان با اثربخشی 60% روی خودتان کست می‌کنید.\n\nاین اتفاق بیش از یک‌بار در هر $proccooldown ثانیه رخ نمی‌دهد."
WoWFA_Data[404436] = "کول‌داون Blade of Justice را 2 ثانیه کاهش می‌دهد."
WoWFA_Data[404512] = "Mastery: Highlord's Judgment روی Judgment و Hammer of Wrath به‌اندازه 50% اثربخشی بیشتری دارد. اگر Greater Judgment را داشته باشید، Judgment یک استک اضافی از Greater Judgment اعمال می‌کند."
WoWFA_En[404542] = "Crusader Strike replaces your auto-attacks and deals $408385s1 Physical damage.\n\nAuto-attack speed is $?a1307499[increased][decreased] by $s2%."
WoWFA_Data[404542] = "Crusader Strike جایگزین حملات خودکار شما می‌شود و $408385s1 آسیب Physical وارد می‌کند.\n\nسرعت حملات خودکار 15% $?a1307499[افزایش][کاهش] می‌یابد."
WoWFA_Data[405278] = "شانس فعال‌شدن Mastery: Highlord's Judgment توسط Judgment به‌اندازه 50% افزایش می‌یابد."
WoWFA_En[405355] = "Wake of Ashes deals significantly reduced damage to secondary targets, but now causes you to lash out $s2 extra times for $405345s1 Radiant damage. "
WoWFA_Data[405355] = "Wake of Ashes به اهداف ثانویه آسیب بسیار کمتری وارد می‌کند، اما اکنون باعث می‌شود 2 بار اضافی با خشم حمله کنید و هر بار $405345s1 آسیب Radiant وارد کنید."
WoWFA_Data[405461] = "Judgment اکنون 2 شارژ دارد."
WoWFA_En[406064] = "Your auto attacks have a $s1% chance to reset the cooldown of Blade of Justice$?s1261113[ and increase the damage of its next cast by $406086s2%.][.]\n\nCritical strikes increase the chance by an additional $s2%."
WoWFA_Data[406064] = "حملات خودکار شما 15% شانس دارند که کول‌داون Blade of Justice را بازنشانی کنند$?s1261113[ و آسیب کست بعدی آن را $406086s2% افزایش دهند][.]\n\nCritical Strikeها این شانس را 10% دیگر افزایش می‌دهند."
WoWFA_En[406101] = "$@spelldesc379017"
WoWFA_Data[406101] = "$?c2[Shield of the Righteous][Word of Glory] grants 20% bonus armor for 4.5 ثانیه."
WoWFA_Data[406154] = "Crusader Strike و حملات خودکار 10% آسیب بیشتری وارد می‌کنند و آسیب Critical Strike آن‌ها 10% بیشتر است."
WoWFA_Data[406157] = "توانایی‌هایی که Holy Power مصرف می‌کنند، 5% آسیب بیشتری وارد می‌کنند.\n\nپس از کست Execution Sentence، 1 توانایی Holy Power بعدی شما هزینه Holy Power خود را بازمی‌گرداند."
WoWFA_En[406468] = "$?s2812[Denounce][Shield of the Righteous] heals you and up to $s3 nearby allies for $403460s1."
WoWFA_Data[406468] = "$?s2812[Denounce][Shield of the Righteous] شما و حداکثر 2 متحد نزدیک را به میزان $403460s1 شفا می‌دهد."
WoWFA_Data[406545] = "به اهدافی که از Expurgation شما در حال سوختن هستند، 5% آسیب Holy بیشتری وارد می‌کنید."
WoWFA_En[406646] = "Crusader Strike loses a charge but is now a combo ability.\n\nTemplar Strike slashes an enemy for $407480s1 Radiant damage and gets followed up by Templar Slash that deals $406647s1 Radiant damage. Templar Slash always critically strikes."
WoWFA_Data[406646] = "Crusader Strike یک شارژ از دست می‌دهد، اما اکنون یک توانایی کمبو است.\n\nTemplar Strike با وارد کردن $407480s1 آسیب Radiant به یک دشمن ضربه می‌زند و سپس Templar Slash ادامه می‌یابد که $406647s1 آسیب Radiant وارد می‌کند. Templar Slash همیشه Critical Strike می‌زند."
WoWFA_Data[406872] = "مدت Avenging Wrath یا Crusade را 4 ثانیه افزایش می‌دهد."
WoWFA_Data[407067] = "Critical Strikeهای توانایی‌هایی که Holy Power تولید می‌کنند، برای 10 ثانیه، به شما 5% Haste می‌دهند."
WoWFA_Data[408459] = "توانایی‌هایی که Holy Power مصرف می‌کنند، 10% شانس دارند توانایی بعدیِ مصرف‌کنندهٔ Holy Power شما را رایگان کنند و آسیب و شفای آن را 10% افزایش دهند."
WoWFA_Data[414073] = "Holy Shock اکنون 2 شارژ دارد و هنگام کست روی دشمن، 50% از هزینه Mana خود را بازمی‌گرداند."
WoWFA_Data[414113] = "Judgment 100% شانس دارد Consecration را در مکان هدف کست کند.\n\nمحدودیت Consecration شامل این اثر نمی‌شود."
WoWFA_Data[414195] = "در حال مبارزه، توانایی‌هایی که Holy Power مصرف می‌کنند 15% شانس دارند باعث شوند Judgment بعدی شما 30% آسیب بیشتر وارد کند و Critical Strike بزند.\n\nفعال‌سازی Avenging Wrath، Awakening را فعال می‌کند."
WoWFA_En[414443] = "$?s2812[Denounce][Shield of the Righteous] deals $414448s1 damage to its first target struck.\n\n$?s2812[Denounce][Shield of the Righteous] now has a $s1% chance to activate Divine Purpose if talented."
WoWFA_Data[414443] = "$?s2812[Denounce][Shield of the Righteous] به نخستین هدفِ ضربه‌خورده $414448s1 آسیب وارد می‌کند.\n\nاگر Divine Purpose را انتخاب کرده باشید، $?s2812[Denounce][Shield of the Righteous] اکنون 35% شانس دارد آن را فعال کند."
WoWFA_Data[414720] = "کول‌داون Lay on Hands به‌اندازه 40% کاهش می‌یابد و 5% از Mana شما را بازمی‌گرداند."
WoWFA_Data[415364] = "Holy Shock بر اساس سلامتی ازدست‌رفته هدف، تا 10% از هزینه Mana خود را بازمی‌گرداند و تا 50% شفا یا آسیب بیشتری وارد می‌کند."
WoWFA_Data[417855] = "شفای Critical Strike مربوط به Holy Shock، Holy Light و Flash of Light به‌اندازه 20% افزایش می‌یابد."
WoWFA_En[425518] = "You gain a stack of Light's Deliverance when you call down an Empyrean Hammer.\n\nWhile $?a137028[Divine Toll][Wake of Ashes] and Hammer of Light are unavailable, you consume $433674U stacks of Light's Deliverance, empowering yourself to cast Hammer of Light an additional time for free."
WoWFA_Data[425518] = "وقتی یک Empyrean Hammer را فرود می‌آورید، یک استک از Light's Deliverance به‌دست می‌آورید.\n\nتا زمانی که $?a137028[Divine Toll][Wake of Ashes] و Hammer of Light در دسترس نیستند، $433674U استک Light's Deliverance را مصرف می‌کنید و خود را تقویت می‌کنید تا Hammer of Light را یک بار اضافی به‌صورت رایگان کست کنید."
WoWFA_En[427445] = "$?a137028[Divine Toll][Wake of Ashes] is replaced with $@spellname427453 for $427441d after it is cast.\n\n$@spellicon427453 $@spellname427453:\n$@spelldesc427453\n|cFFFFFFFFCosts 5 Holy Power.\n"
WoWFA_Data[427445] = "$?a137028[Divine Toll][Wake of Ashes] پس از کست‌شدن، برای 20 ثانیه با Hammer of Light جایگزین می‌شود.\n\n Hammer of Light:\nHammer down your enemy with the power of the Light, dealing $s1 Holy damage and $429826s1 Holy damage up to 7 nearby enemies. \n\nAdditionally, calls down Empyrean Hammers from the sky to strike 3 nearby enemies for $431398s1 Holy damage each.\n\n|cFFFFFFFFهزینه: 5 Holy Power."
WoWFA_En[431377] = "Casting $?c1[Holy Prism or Divine Toll]?c3[Wake of Ashes][] causes your next $s1 Holy Power spending abilities to apply Dawnlight on your target, dealing $431380o1 Radiant damage or $431381o1 healing over $431380d.\n\n$431581s1% of Dawnlight's damage and healing radiates to nearby allies or enemies, reduced beyond $431581s2 targets.$?c1[\n\nDawnlight's healing does not transfer to Beacon of Light.][]"
WoWFA_Data[431377] = "کست کردن $?c1[Holy Prism یا Divine Toll]?c3[Wake of Ashes][] باعث می‌شود 2 توانایی بعدی شما که Holy Power مصرف می‌کند، Dawnlight را روی هدف اعمال کند و طی 8 ثانیه، $431380o1 آسیب Radiant یا $431381o1 شفا وارد کند.\n\n8% از آسیب و شفای Dawnlight به متحدان یا دشمنان نزدیک ساطع می‌شود و پس از 5 هدف کاهش می‌یابد.$?c1[\n\nشفای Dawnlight به Beacon of Light منتقل نمی‌شود.][]"
WoWFA_En[431402] = "$?c1[Critical Strike chance of Holy Shock and Light of Dawn increased by $s1%.]?c3[Critical Strike chance of Hammer of Wrath and Divine Storm increased by $s2%.][]"
WoWFA_Data[431402] = "$?c1[شانس Critical Strike مربوط به Holy Shock و Light of Dawn به‌اندازه 5% افزایش می‌یابد.]?c3[شانس Critical Strike مربوط به Hammer of Wrath و Divine Storm به‌اندازه 10% افزایش می‌یابد.][]"
WoWFA_Data[431404] = "Haste به‌اندازه 5% افزایش می‌یابد."
WoWFA_Data[431406] = "وقتی سلامتی‌تان بیش از 80% باشد، سرعت حرکت 5% افزایش می‌یابد.\n\nوقتی سلامتی‌تان به کمتر از 35% برسد، سرعت حرکت شما به‌مدت 5 ثانیه به‌اندازه 40% افزایش می‌یابد. این اثر بیش از یک‌بار در هر 1 دقیقه رخ نمی‌دهد."
WoWFA_Data[431407] = "هنگام منقضی شدن یا تمدید Dawnlight، روی متحدان Eternal Flame را برای 6 ثانیه یا روی دشمنان Greater Judgment را باقی می‌گذارد."
WoWFA_En[431413] = "$?c1[Holy Shock and Light of Dawn critical strikes cause the target to be healed for an additional $431415o1 over $431415d.]?c3[Hammer of Wrath and Divine Storm critical strikes cause the target to burn for an additional $431414o1 Radiant damage over $431414d.][]"
WoWFA_Data[431413] = "$?c1[Critical Strikeهای Holy Shock و Light of Dawn باعث می‌شوند هدف طی 4 ثانیه به‌اندازه $431415o1 شفا اضافه دریافت کند.]?c3[Critical Strikeهای Hammer of Wrath و Divine Storm باعث می‌شوند هدف طی 4 ثانیه به‌اندازه $431414o1 آسیب Radiant اضافه دریافت کند.][]"
WoWFA_Data[431423] = "Dawnlight سرعت حرکت دشمنان را 50% کاهش می‌دهد و سرعت حرکت متحدان را 20% افزایش می‌دهد."
WoWFA_En[431425] = "You link to your Dawnlights within $s8 yds, causing $431911s1 Radiant damage to enemies or $431939s1 healing to allies that pass through the beams, reduced beyond $?c3[$s9][$s6] targets."
WoWFA_Data[431425] = "به Dawnlightهای خود در فاصله 30 یارد پیوند می‌خورید و به دشمنانی که از پرتوها عبور می‌کنند $431911s1 آسیب Radiant یا به متحدانی که از آن‌ها عبور می‌کنند $431939s1 شفا وارد می‌کنید؛ پس از $?c3[8][5] هدف کاهش می‌یابد."
WoWFA_Data[431463] = "Hammer of Light هنگام کست، فوراً 2 Empyrean Hammer بر هدف شما فرود می‌آورد."
WoWFA_En[431474] = "$?c1[Light of Dawn and Holy Shock have a $s1% chance to cast again at $s2% effectiveness.]?c3[Divine Storm and Hammer of Wrath have a $s1% chance to cast again at $s2% effectiveness.][]"
WoWFA_Data[431474] = "$?c1[Light of Dawn و Holy Shock 15% شانس دارند دوباره با اثربخشی 30% کست شوند.]?c3[Divine Storm و Hammer of Wrath 15% شانس دارند دوباره با اثربخشی 30% کست شوند.][]"
WoWFA_Data[431480] = "توانایی‌هایی که Holy Power مصرف می‌کنند، 3% آسیب و شفا بیشتر وارد می‌کنند."
WoWFA_Data[431482] = "هر 5 ثانیه، آسیب یا شفای Dawnlight بعدی شما 5% افزایش می‌یابد و این اثر تا 10 استک می‌شود.\n\nاستک‌های Morning Star خارج از مبارزه دو برابر سریع‌تر جمع می‌شوند."
WoWFA_Data[431533] = "پس از کست Hammer of Light، برای 8 ثانیه، هر 2 ثانیه یک Empyrean Hammer بر هدفی نزدیک فرود می‌آورید."
WoWFA_Data[431551] = "وقتی Empyrean Hammer، Critical Strike می‌زند، 50% از آسیب آن به دشمنان نزدیک وارد می‌شود.\n\nدشمنانی که با این افکت ضربه می‌خورند، برای 8 ثانیه، 5% آسیب کمتری به شما وارد می‌کنند."
WoWFA_En[431687] = "$?a137028[Crusader Strike, Hammer of Wrath and Judgment][Crusader Strike, Hammer of Wrath and Blade of Justice] extend the duration of Shake the Heavens by $s1 sec."
WoWFA_Data[431687] = "$?a137028[Crusader Strike، Hammer of Wrath و Judgment][Crusader Strike، Hammer of Wrath و Blade of Justice] مدت Shake the Heavens را 1 ثانیه افزایش می‌دهند."
WoWFA_En[431730] = "$?a137028[Divine Toll][Wake of Ashes] surrounds you with a Holy barrier for $?a137028[$s1][$s4]% of your maximum health.\n\nHammer of Light heals you for $?a137028[$s2][$s5]% of your maximum health, increased by $?a137028[$s3][$s6]% for each additional target hit. Any overhealing done with this effect gets converted into a Holy barrier instead."
WoWFA_Data[431730] = "$?a137028[Divine Toll][Wake of Ashes] شما را با یک مانع Holy به‌اندازه $?a137028[15][10]% از حداکثر سلامتی‌تان احاطه می‌کند.\n\nHammer of Light شما را به‌اندازه $?a137028[15][5]% از حداکثر سلامتی‌تان شفا می‌دهد؛ این مقدار به‌ازای هر هدف اضافیِ ضربه‌خورده، $?a137028[2][1]% افزایش می‌یابد. هر شفای اضافی ایجادشده با این افکت، به‌جای آن به مانع Holy تبدیل می‌شود."
WoWFA_En[432459] = "Will the Light to coalesce and become manifest as a Holy Armament, wielded by your friendly target.\n\n$@spellicon432496 $@spellname432496:\n\n$@spelldesc432496\n\nBecomes Sacred Weapon after use.$?c1[\n\n|cFFFFFFFFGenerates $s2 Holy Power.][]"
WoWFA_Data[432459] = "از Light بخواهید متراکم شود و به شکل یک Holy Armament که هدف دوست شما آن را به‌دست می‌گیرد، پدیدار شود.\n\n Holy Bulwark:\n\nWhile wielding a Holy Bulwark, gain an absorb shield for 15% of your max health and an additional 2% every 2 sec. Lasts 20 ثانیه.\n\nپس از استفاده به Sacred Weapon تبدیل می‌شود.$?c1[\n\n|cFFFFFFFFمقدار 3 Holy Power تولید می‌کند.][]"
WoWFA_En[432463] = "$?a137028[Shield of the Righteous and Word of Glory]?s383328[Final Verdict][Templar's Verdict]$?a137027[ and Divine Storm][] calls down an Empyrean Hammer on a nearby enemy.\n\nWhile Shake the Heavens is active, this effect calls down an additional Empyrean Hammer."
WoWFA_Data[432463] = "$?a137028[Shield of the Righteous و Word of Glory]?s383328[Final Verdict][Templar's Verdict]$?a137027[ و Divine Storm][] یک Empyrean Hammer را بر دشمنی نزدیک فرود می‌آورد.\n\nوقتی Shake the Heavens فعال است، این افکت یک Empyrean Hammer اضافی نیز فرود می‌آورد."
WoWFA_Data[432615] = "شانس Critical Strike زدن Empyrean Hammer به‌اندازه 10% افزایش می‌یابد."
WoWFA_En[432626] = "Hammer of Light $?a137028[grants Shield of the Righteous, erupts a Consecration beneath its target][applies Judgment to its targets], and increases your Haste by $432629s1% for $432629d."
WoWFA_Data[432626] = "Hammer of Light $?a137028[Shield of the Righteous می‌دهد و یک Consecration زیر هدفش ایجاد می‌کند][Judgment را روی اهدافش اعمال می‌کند] و Haste شما را به‌اندازه 12% برای 6 ثانیه افزایش می‌دهد."
WoWFA_Data[432802] = "اگر Armamentی به یک متحد ببخشید، خودتان نیز از مزایای آن بهره‌مند می‌شوید.\n\nاگر Armamentی به خودتان ببخشید، یک متحد نزدیک نیز از مزایای آن بهره‌مند می‌شود."
WoWFA_Data[432804] = "کول‌داون Holy Armaments 20% کاهش می‌یابد."
WoWFA_Data[432821] = "اثر Aura فعال شما روی اهداف دارای Armamentهای شما 33% افزایش می‌یابد."
WoWFA_En[432866] = "When an Armament fades from you, the cooldown of Lay on Hands is reduced by ${$s1/1000}.1 sec and you gain $?a137028[Shining Light][Infusion of Light]."
WoWFA_Data[432866] = "وقتی یک Armament از شما محو می‌شود، کول‌داون Lay on Hands به‌اندازهٔ 15 ثانیه کاهش می‌یابد و $?a137028[Shining Light][Infusion of Light] را به‌دست می‌آورید."
WoWFA_En[432919] = "Consuming $?a137028[Shining Light][Infusion of Light] reduces the cooldown of Holy Armaments by ${$s1/1000}.1 sec."
WoWFA_Data[432919] = "مصرف کردن $?a137028[Shining Light][Infusion of Light] کول‌داون Holy Armaments را به‌اندازهٔ 3 ثانیه کاهش می‌دهد."
WoWFA_En[432929] = "Divine Toll summons Divine Hammers that spin around you for $198034d.\n\n$@spellicon198034$@spellname198034\n$@spelldesc198034"
WoWFA_Data[432929] = "Divine Toll، Divine Hammers را فراخوانی می‌کند که برای 8 ثانیه اطراف شما می‌چرخند.\n\nDivine Hammer\nStrikes all enemies nearby for $?s405289[${$198137sw1*1.05} Radiant][$198137sw1 Holy] damage every 2 sec. Deals reduced damage beyond 8 targets."
WoWFA_Data[432964] = "اسپل‌ها و توانایی‌های شما شانس دارند برای یک متحد نزدیک Holy Armament پدیدار کنند."
WoWFA_Data[432977] = "کست Judgment، آسیب Empyrean Hammer را برای 10 ثانیه به‌اندازه 5% افزایش می‌دهد.\n\nاعمال متعدد می‌توانند روی هم قرار بگیرند."
WoWFA_Data[432990] = "Divine Steed، 2 ثانیه بیشتر دوام می‌آورد و در طول 3 ثانیه نخست، سرعت حرکت شما را 30% دیگر افزایش می‌دهد."
WoWFA_Data[432992] = "از Blessing of Sacrifice، 20% آسیب کمتری دریافت می‌کنید و هر بار که هدف آن آسیب می‌بیند، 4% سرعت حرکت به‌دست می‌آورید؛ حداکثر تا 40%."
WoWFA_Data[433011] = "Avenging Wrath یک Sacred Weapon اضافی احضار می‌کند و در طول Avenging Wrath، Sacred Weapon شما روی هدف‌تان اسپل کست می‌کند و اثرات توانایی‌های Holy Power شما را بازتاب می‌دهد."
WoWFA_En[433015] = "Casting a Holy Power ability increases the damage and healing of your next $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?s137029[Holy Shock][Crusader Strike] by $433019s1%."
WoWFA_Data[433015] = "کست کردن یک توانایی Holy Power، آسیب و شفای $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?s137029[Holy Shock][Crusader Strike] بعدی شما را 100% افزایش می‌دهد."
WoWFA_En[433106] = "For each Holy Power ability cast, your next Consecration deals $?a137029[$<holy>][$<prot>] damage immediately, split across all enemies.\n\nUp to $s3 nearby $Lally is:allies are each; healed for $?a137029[$s5][$s4]% of the damage amount."
WoWFA_Data[433106] = "به‌ازای هر توانایی Holy Power که کست می‌کنید، Consecration بعدی شما بلافاصله $?a137029[$<holy>][$<prot>] آسیب وارد می‌کند که میان همهٔ دشمنان تقسیم می‌شود.\n\nتا 3 متحد نزدیک، هرکدام به‌اندازهٔ $?a137029[100][30]% مقدار آسیب شفا می‌یابند."
WoWFA_Data[433568] = "سلاح خود را با نیروی Light آغشته کنید؛ Armor شما 5% و استت اصلی شما 2% افزایش می‌یابد.\n\nبه‌مدت 1 ساعت دوام دارد."
WoWFA_Data[433583] = "سلاح خود را با نیروی Light آغشته کنید؛ Stamina شما 3% افزایش می‌یابد و توانایی‌های Holy Power شما گاهی انفجاری از شفا پیرامون یک هدف آزاد می‌کنند.\n\nبه‌مدت 1 ساعت دوام دارد."
WoWFA_En[433718] = "Judgment critical strikes cause a shockwave around the target, $?c1[healing to up to $s3 injuried allies for $433722s1][dealing $433717s1 damage to enemies within $433717a1 yards. Damage reduced above $s4 targets]."
WoWFA_Data[433718] = "Critical Strikeهای Judgment موجی ضربه‌ای پیرامون هدف ایجاد می‌کنند؛ $?c1[تا 5 متحد زخمی را به‌اندازهٔ $433722s1 شفا می‌دهند][به دشمنان در فاصلهٔ 5 یاردی $433717s1 آسیب وارد می‌کنند. آسیب بالاتر از 5 هدف کاهش می‌یابد]."
WoWFA_En[439760] = "After you cast $?c1[Holy Prism or Divine Toll]?c3[Wake of Ashes][], gain Divine Purpose.\n\n$?c1[$@spellicon223819 $@spellname223819\n$@spellaura223819]?c3[$@spellicon408458 $@spellname408458\n$@spellaura408458][]"
WoWFA_Data[439760] = "پس از کست کردن $?c1[Holy Prism یا Divine Toll]?c3[Wake of Ashes][]، Divine Purpose را به‌دست می‌آورید.\n\n$?c1[ Divine Purpose\nYour next Holy Power spending ability is free and deals 15% increased damage and healing.]?c3[ Divine Purpose\nYour next Holy Power spending ability is free and deals 10% increased damage and healing.][]"
WoWFA_En[445200] = "$?c1[The healing and damage of Holy Shock is increased by $s1%.]?c3[Your damage and healing over time effects have a chance to increase the damage of your next Judgment by $445206s1%.][]"
WoWFA_Data[445200] = "$?c1[شفا و آسیب Holy Shock به‌اندازه 15% افزایش می‌یابد.]?c3[اثرات آسیب و شفای در طول زمان شما شانس دارند آسیب Judgment بعدی‌تان را 50% افزایش دهند.][]"
WoWFA_Data[446663] = "وقتی Truth's Wake، Critical Strike می‌زند، مدت آن 2 ثانیه افزایش می‌یابد.\n\nسایر افکت‌های آسیب در طول زمان شما به اهداف متأثر از Truth's Wake، 30% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[447985] = "وقتی سلامتی‌تان بیش از 80% است، شفای Holy Shock به‌اندازه 20% افزایش می‌یابد، اما به‌اندازه 30% از مقدار شفا روی شما جذب شفا ایجاد می‌کند که تا زمان از بین رفتن، مانع شفای Beacon of Light از شما می‌شود."
WoWFA_En[448040] = "Light of the Martyr's health threshold is reduced to ${$s4+$s1}% and increases Holy Shock's healing by an additional $448087s1% for every $t2 sec Light of the Martyr is active, stacking up to $448087u times.\n\nWhile below ${$s4+$s1}% health, the light urgently heals you for $448086s1 every $448086t1 sec."
WoWFA_Data[448040] = "آستانه سلامتی Light of the Martyr به 70% کاهش می‌یابد و تا زمانی که Light of the Martyr فعال است، به‌ازای هر 5 ثانیه شفاهای Holy Shock را 5% دیگر افزایش می‌دهد؛ این اثر تا 3 استک می‌شود.\n\nوقتی سلامتی‌تان کمتر از 70% باشد، نور هر 1 ثانیه شما را فوراً به‌اندازه $448086s1 شفا می‌دهد."
WoWFA_En[458359] = "$?s231895[Crusade][Avenging Wrath] is replaced with Radiant Glory.\n\n$@spellicon458359$@spellname458359\nWake of Ashes activates $?s231895[Crusade for $454373d][Avenging Wrath for $454351d]."
WoWFA_Data[458359] = "$?s231895[Crusade][Avenging Wrath] با Radiant Glory جایگزین می‌شود.\n\nRadiant Glory\nWake of Ashes، $?s231895[Crusade را برای 8 ثانیه][Avenging Wrath را برای 8 ثانیه] فعال می‌کند."
WoWFA_Data[460720] = "زمان کست Turn Evil به‌اندازهٔ 100% کاهش می‌یابد."
WoWFA_Data[461243] = "متحدان دارای Beacon of Light، 5% آسیب کمتری دریافت می‌کنند."
WoWFA_Data[461244] = "50% از شفای اضافی Holy Shock به سپر جذب آسیب تبدیل می‌شود. مقدار سپر نمی‌تواند از 10% حداکثر سلامتی شما بیشتر شود."
WoWFA_Data[461246] = "Holy Shock هنگام کست شدن 12% شانس دارد یک شارژ را بازگرداند و شفای آن 10% افزایش می‌یابد."
WoWFA_En[461273] = "Judgment heals you for $461546s1 and its mana cost is reduced by $s1%. $s2% of overhealing from this effect is transferred onto $s3 allies within $461529a1 yds."
WoWFA_Data[461273] = "Judgment شما را به‌اندازه $461546s1 شفا می‌دهد و هزینه Mana آن 30% کاهش می‌یابد. 50% از شفای اضافی این اثر به 2 متحد در فاصله 40 یارد منتقل می‌شود."
WoWFA_Data[461278] = "Word of Glory و Light of Dawn بر اساس سلامتی فعلی هدف، تا 30% شانس بیشتر برای Critical Strike زدن به‌دست می‌آورند. اهداف با سلامتی کمتر احتمال بیشتری دارد Critical Strike بخورند."
WoWFA_Data[461287] = "12% از شفای Word of Glory و Light of Dawn به آسیب Holy تبدیل می‌شود که به یک دشمن نزدیک ضربه می‌زند."
WoWFA_Data[469279] = "وقتی سلامتی یک متحد در فاصلهٔ 40 یارد کمتر از 35% باشد و شما تحت اثر از دست دادن کنترل نباشید، به‌طور خودکار Blessing of Sacrifice را روی او کست می‌کنید.\n\nاین اثر، 100% از کول‌داون Blessing of Sacrifice را فعال می‌کند."
WoWFA_En[469304] = "Divine Steed also grants Blessing of Freedom for ${$s1/1000}.1 sec.\n\n$@spellicon1044 $@spellname1044:\n$@spelldesc1044"
WoWFA_Data[469304] = "Divine Steed همچنین برای 3 ثانیه Blessing of Freedom می‌دهد.\n\n Blessing of Freedom:\nبه یک عضو پارتی یا رید Blessing می‌دهد و برای 8 ثانیه او را در برابر اثرات مختل‌کنندهٔ حرکت ایمن می‌کند$?s199325[ و سرعت حرکتش را 30% افزایش می‌دهد][]."
WoWFA_En[469309] = "Melee and ranged attackers receive $469311s1 Holy damage each time they strike you during $?c2[Ardent Defender][Divine Protection] and Divine Shield."
WoWFA_Data[469309] = "مهاجمان نزدیک و دوربرد، هنگام فعال بودن $?c2[Ardent Defender][Divine Protection] و Divine Shield، هر بار که به شما ضربه بزنند $469311s1 آسیب Holy دریافت می‌کنند."
WoWFA_Data[469316] = "مدت اثرات استان روی شما 20% کاهش می‌یابد."
WoWFA_Data[469317] = "Turn Evil اکنون روی 5 دشمن اضافی اثر می‌گذارد."
WoWFA_Data[469321] = "Blessing of Sacrifice اکنون تمام اثرات Poison و Disease را حذف و از آن‌ها جلوگیری می‌کند."
WoWFA_Data[469325] = "کول‌داون Blinding Light به‌اندازهٔ 15 ثانیه کاهش می‌یابد."
WoWFA_Data[469337] = "توانایی‌هایی که Holy Power مصرف می‌کنند، 2% آسیب و شفای بیشتری دارند."
WoWFA_Data[469409] = "کول‌داون Divine Steed به‌اندازهٔ 20% کاهش می‌یابد، اما مدت آن 40% کاهش می‌یابد."
WoWFA_En[469411] = "After $?c1[Cleanse][Cleanse Toxins] successfully removes an effect from an ally, they are healed for ${$469413s1*$s1}."
WoWFA_Data[469411] = "پس از آن‌که $?c1[Cleanse][Cleanse Toxins] با موفقیت اثری را از یک متحد حذف کند، او به میزان ${$469413s1*$s1} شفا می‌یابد."
WoWFA_Data[469416] = "10% از تمام شفایی که از منابع دیگر دریافت می‌کنید، تا 4 متحد نزدیک را به‌طور مساوی میان آن‌ها شفا می‌دهد."
WoWFA_En[469434] = "Flash of Light $?c1[and Holy Light are][is] $s1% more effective on your allies and $s2% of the healing done also heals you."
WoWFA_Data[469434] = "Flash of Light $?c1[و Holy Light][] روی متحدان شما 30% اثربخش‌تر است و 40% از شفای انجام‌شده، شما را نیز شفا می‌دهد."
WoWFA_En[469439] = "$?c2[Ardent Defender][Divine Protection] increases healing taken by $s1% for its duration."
WoWFA_Data[469439] = "$?c2[Ardent Defender][Divine Protection] در مدت خود، شفای دریافتی را 15% افزایش می‌دهد."
WoWFA_Data[469445] = "مدت Forbearance شما به‌اندازهٔ 10 ثانیه کاهش می‌یابد."
WoWFA_Data[469476] = "شعاع Auraهای شما به‌اندازهٔ 20 یارد افزایش می‌یابد."
WoWFA_Data[469701] = "وقتی شما یا متحدی که Holy Bulwark در دست دارد، بیش از حداکثر سلامتی شفا می‌یابید، 100% از شفای بیش‌ازحد را به متحدتان منتقل کنید.\n\nوقتی شما یا متحدی که Sacred Weapon در دست دارد به کمتر از 40% سلامتی برسید، سلامتی‌تان را بلافاصله و هر 1 ثانیه، به‌مدت 4 ثانیه بازتوزیع کنید. در هر کست فقط یک‌بار می‌تواند رخ دهد."
WoWFA_Data[469770] = "سرعت حرکت متحدانی که Blessingهای شما روی آن‌ها اثر دارند، 15% افزایش می‌یابد."
WoWFA_Data[469780] = "Divine Steed کول‌داون توانایی اصلی حرکتِ 4 متحد نزدیک را به‌اندازهٔ 3 ثانیه کاهش می‌دهد.\n\nسرعت حرکت شما 3% افزایش می‌یابد."
WoWFA_Data[469883] = "Enemies struck by Avenger's Shield burn with holy fire, suffering 100% additional Radiant damage over 5 ثانیه."
WoWFA_En[469886] = "Successfully $?c1[dispelling a harmful effect][interrupting an enemy spellcast] reduces $?c1[Cleanse's cooldown by ${$s3/1000}.1 sec][Rebuke's cooldown by ${$s1/1000}.1 sec]. Effect increased by $s2% while wielding a Holy Armament."
WoWFA_Data[469886] = "موفقیت در $?c1[پاک‌سازی یک اثر مضر][قطع کردن کست دشمن] کول‌داون $?c1[Cleanse را به‌اندازهٔ 1 ثانیه][Rebuke را به‌اندازهٔ 1 ثانیه] کاهش می‌دهد. هنگام استفاده از یک Holy Armament، اثر 100% افزایش می‌یابد."
WoWFA_En[1232616] = "$@spellicon156910 $@spellname156910:\nAllies with Beacon of Light or Beacon of Faith are healed for $53563s5 every $53563t5 sec.\n\n$@spellicon200025 $@spellname200025:\nBeacon of Virtue instantly heals allies for $1232617s1."
WoWFA_Data[1232616] = " Beacon of Faith:\nمتحدان دارای Beacon of Light یا Beacon of Faith هر 3 ثانیه به‌اندازه $53563s5 شفا می‌یابند.\n\n Beacon of Virtue:\nمتحدان دارای Beacon of Virtue فوراً به‌اندازه $1232617s1 شفا می‌یابند."
WoWFA_En[1241275] = "Activating Avenging Wrath releases the Light within yourself, healing $200652s2 injured allies instantly and an injured ally every $200652t1 sec within $200653A1 yds for $200654s1.\n\nAllies healed also receive $200654s2% increased healing from your Holy Light, Flash of Light, and Holy Shock spells for $200654d. "
WoWFA_Data[1241275] = "فعال‌سازی Avenging Wrath، Light درون شما را آزاد می‌کند و فوراً 5 متحد زخمی و سپس هر 1 ثانیه یک متحد زخمی را در فاصله 40 یارد به‌اندازه $200654s1 شفا می‌دهد.\n\nمتحدان شفایافته همچنین به‌مدت 12 ثانیه از جادوهای Holy Light، Flash of Light و Holy Shock شما 10% شفا بیشتر دریافت می‌کنند."
WoWFA_En[1241288] = "During Avenging Wrath, Judgment is empowered into Hammer of Wrath.$?c3[\n\n$@spellicon24275$@spellname24275\n$@spelldesc24275][\n\n$@spellicon1241413 $@spellname1241413\n$@spelldesc1241413]"
WoWFA_Data[1241288] = "هنگام Avenging Wrath، Judgment به Hammer of Wrath تقویت می‌شود.$?c3[\n\nHammer of Wrath\nHurls a divine hammer that strikes an enemy for $<damage> Holy damage.\n\n|cFFFFFFFFGenerates 1 Holy Power.][\n\n Hammer of Wrath\nHurls a divine hammer that strikes an enemy for $<damage> $?s403664[Holystrike][Holy] damage.\n\n|cFFFFFFFFGenerates 1 Holy Power.]"
WoWFA_Data[1241358] = "Critical Strikeهای Judgment، Word of Glory بعدی شما را تقویت می‌کنند تا Light of Dawn را با اثربخشی 30% به‌طور خودکار فعال کند."
WoWFA_Data[1241511] = "کول‌داون Avenging Wrath به‌اندازه 30 ثانیه کاهش می‌یابد، اما مدت آن 5 ثانیه کمتر می‌شود.\n\nکول‌داون Avenging Crusader به‌اندازه 30 ثانیه کاهش می‌یابد، اما مدت آن 3 ثانیه کمتر می‌شود."
WoWFA_Data[1241542] = "فعال‌سازی Aura Mastery همچنین Divine Toll را با اثربخشی 200% کست می‌کند."
WoWFA_Data[1241714] = "Word of Glory و Light of Dawn اکنون 15% از شفای خود را به سپر جذب آسیب تبدیل می‌کنند."
WoWFA_Data[1241805] = "هنگامی که سلامتی در حداکثر مقدار است، اهداف دارای Beacon of Light هر 3 ثانیه سپر جذبی معادل 2% از سلامتی‌شان ایجاد می‌کنند؛ تا سقف 6%."
WoWFA_Data[1241945] = "آسیب دریافتی تا 10% کاهش می‌یابد و با کاهش سلامتی شما، این کاهش بیشتر می‌شود."
WoWFA_Data[1241958] = "Hammer of Wrath بر اساس سلامتی هدف، تا 50% آسیب اضافی وارد می‌کند. اهداف با سلامتی کمتر آسیب بیشتری دریافت می‌کنند."
WoWFA_En[1242008] = "Activating Avenging Wrath calls upon the Light to empower you, causing your next $?s216331[Holy Light][$s1 Holy Lights] to be instant cast and cost $414273s2% less mana."
WoWFA_Data[1242008] = "فعال‌سازی Avenging Wrath، Light را فرامی‌خواند تا شما را تقویت کند و باعث شود $?s216331[Holy Light][2 Holy Light] بعدی شما کست فوری باشد و 50% Mana کمتری هزینه کند."
WoWFA_Data[1244019] = "به‌اندازهٔ دست‌کم 125% آسیبی که Refining Fire وارد می‌کند شفا می‌یابید؛ با کاهش سلامتی‌تان، این مقدار تا حداکثر 300% افزایش می‌یابد."
WoWFA_Data[1244070] = "کست کردن Avenger's Shield باعث می‌شود Consecration بلافاصله دوباره آسیب و شفای خود را با اثربخشی 100% اعمال کند."
WoWFA_Data[1244878] = "در حال مبارزه، Beacon of the Savior را روی متحدِ دارای کمترین سلامتی در فاصله 30 یارد اعمال می‌کنید؛ شفاهای مستقیم شما روی دیگران، آن متحد را نیز به‌اندازه 10% مقدار شفا شفا می‌دهد.\n\nاگر این Beacon هدفی را بیش از حداکثر سلامتی‌اش شفا دهد یا سلامتی متحدی به کمتر از 50% برسد، Beacon of the Savior به متحدِ دارای کمترین سلامتی در فاصله 30 یارد منتقل می‌شود."
WoWFA_Data[1245354] = "وقتی Consecration به یک هدف تنها اصابت کند، 100% آسیب بیشتری وارد می‌کند."
WoWFA_Data[1245367] = "Beacon of the Savior مقدار شفا را 10% بیشتر منتقل می‌کند و متحدان دارای Beacon of the Savior از شما 10% شفا بیشتر دریافت می‌کنند."
WoWFA_En[1245368] = "Every $t1 sec or when Beacon of the Savior transfers to a new injured target, they are granted an absorb shield that prevents the next $1245369s1 damage and reduces damage taken by $1245369s2% for $1245369d.\n\nBeacon of the Savior now additionally follows the target of your Holy Light and Flash of Light spells once every $proccooldown sec."
WoWFA_Data[1245368] = "هر 8 ثانیه یا هنگام انتقال Beacon of the Savior به هدف زخمی جدید، به آن‌ها سپر جذب آسیب داده می‌شود که از $1245369s1 آسیب بعدی جلوگیری می‌کند و آسیب دریافتی را به‌مدت 15 ثانیه به‌اندازه 10% کاهش می‌دهد.\n\nBeacon of the Savior اکنون علاوه بر این، هر $proccooldown ثانیه یک‌بار هدف جادوهای Holy Light و Flash of Light شما را دنبال می‌کند."
WoWFA_Data[1245891] = "Consecration شما را به‌اندازهٔ 375% آسیبی که وارد می‌کند شفا می‌دهد."
WoWFA_Data[1245979] = "در خارج از مبارزه، Divine Steed برای مدت خود و 4 ثانیه پس از محو شدنش، Shield of the Righteous می‌دهد."
WoWFA_Data[1246481] = "Guardian of Ancient Kings، 1 شارژ اضافی دارد."
WoWFA_En[1246488] = "Judgment chains to $s1 additional $Ltarget;targets at ${$275779f1*100}% effectiveness."
WoWFA_Data[1246488] = "Judgment با اثربخشی ${$275779f1*100}% به 2 هدف اضافی زنجیره می‌شود."
WoWFA_Data[1253598] = "Avenging Wrath اکنون 2% Haste به شما می‌دهد.\n\nهر Holy Power مصرف‌شده در طول Avenging Wrath، Haste را 2% دیگر افزایش می‌دهد؛ حداکثر تا 20%."
WoWFA_Data[1260429] = "Divine Toll، 2 بار اضافی روی هدف شما با اثربخشی 100% کست می‌شود."
WoWFA_En[1261111] = "Avenging Wrath further increases the damage of $?s383328[Final Verdict][Templar's Verdict] and Divine Storm by $s1%."
WoWFA_Data[1261111] = "Avenging Wrath آسیب $?s383328[Final Verdict][Templar's Verdict] و Divine Storm را 10% دیگر افزایش می‌دهد."
WoWFA_En[1261113] = "$?s402912[Righteous Cause][Art of War] increases the damage of your next Blade of Justice by $s1% and can now accumulate an additional time."
WoWFA_Data[1261113] = "$?s402912[Righteous Cause][Art of War] آسیب Blade of Justice بعدی شما را 80% افزایش می‌دهد و اکنون می‌تواند یک بار دیگر انباشته شود."
WoWFA_En[1261159] = "$?s402912[Righteous Cause][Art of War] further empowers Blade of Justice to unleash a wave of Holy energy, dealing ${$1261160s1*$<mult>} Holy damage to its primary target and $1261160s1 Holy damage to all other enemies in its path."
WoWFA_Data[1261159] = "$?s402912[تلنت Righteous Cause][تلنت Art of War] قدرت Blade of Justice را باز هم افزایش می‌دهد تا موجی از انرژی Holy رها کند؛ به هدف اصلی خود ${$1261160s1*$<mult>} آسیب Holy و به همه دشمنان دیگر در مسیرش $1261160s1 آسیب Holy وارد می‌کند."
WoWFA_Data[1261525] = "Empyrean Hammer، 20% آسیب Critical Strike بیشتری وارد می‌کند و Critical Strikeهای آن 50% شانس دارند یک استک اضافی از Light's Deliverance بدهند."
WoWFA_En[1261562] = "Divine Protection reduces damage taken by an additional $s2% and casts Shield of Vengeance.\n\n$@spellicon184662$@spellname184662\n$@spelldesc184662"
WoWFA_Data[1261562] = "Divine Protection آسیب دریافتی را 10% دیگر کاهش می‌دهد و Shield of Vengeance را کست می‌کند.\n\nShield of Vengeance\nCreates a barrier of holy light that absorbs $<shield> damage for 10 ثانیه.\n\nWhen the shield expires, it bursts to inflict Holy damage equal to the total amount absorbed, divided among all nearby enemies."
WoWFA_En[1263252] = "$?a137028[Judgment]?s383328[Final Verdict][Templar's Verdict] damage increased by $?a137028[$s2%][$s1%]."
WoWFA_Data[1263252] = "آسیب $?a137028[Judgment]?s383328[Final Verdict][Templar's Verdict] به‌اندازه $?a137028[30%][25%] افزایش می‌یابد."
WoWFA_En[1263782] = "$?c3[You have a $s1% chance to gain Blessing of An'she and generate $s2 Holy Power after casting Avenging Wrath.\n\nDuring Avenging Wrath, Hammer of Wrath casts Blade of Justice at $s3% effectiveness.][Infusion of Light occurs $s4% more often during Avenging Wrath.]"
WoWFA_Data[1263782] = "$?c3[پس از کست کردن Avenging Wrath، 100% شانس دارید Blessing of An'she را به‌دست آورید و 2 Holy Power تولید کنید.\n\nدر طول Avenging Wrath، Hammer of Wrath، Blade of Justice را با اثربخشی 100% کست می‌کند.][Infusion of Light در طول Avenging Wrath، $s4% بیشتر رخ می‌دهد.]"
WoWFA_En[1263787] = "$?c1[Dawnlight's duration is increased by ${$s1/1000}.1 sec when it heals an ally with full health.][Dawnlight's duration is increased by ${$s2/1000}.1 sec whenever struck by Divine Storm or Templar's Verdict.\n\nWhen 2 Dawnlights are struck by Divine Storm, their durations are extended by an additional ${$s3/1000}.1 sec.]"
WoWFA_Data[1263787] = "$?c1[وقتی Dawnlight متحدی با سلامتی کامل را شفا دهد، مدت آن 0.5 ثانیه افزایش می‌یابد.][هر زمان که Dawnlight با Divine Storm یا Templar's Verdict ضربه بخورد، مدت آن 0.3 ثانیه افزایش می‌یابد.\n\nوقتی 2 Dawnlight با Divine Storm ضربه بخورند، مدتشان 0.5 ثانیه دیگر افزایش می‌یابد.]"
WoWFA_Data[1263920] = "شانس Critical Strike مربوط به Dawnlight در طول Avenging Wrath به‌اندازه 15% افزایش می‌یابد."
WoWFA_Data[1265541] = "مدت Fear روی شما 20% کاهش می‌یابد. این اثر هنگام Avenging Wrath به 60% افزایش می‌یابد."
WoWFA_En[1265549] = "Killing an enemy that yields experience or honor causes you to explode with holy energy, healing up to $s1 nearby allies and yourself for $1265595s1, split evenly among them."
WoWFA_Data[1265549] = "کشتن دشمنی که تجربه یا Honor می‌دهد، باعث می‌شود با انرژی Holy منفجر شوید و تا 5 متحد نزدیک و خودتان را به میزان $1265595s1 شفا دهید؛ این مقدار به‌طور مساوی میان آن‌ها تقسیم می‌شود."
WoWFA_Data[1267203] = "Judgment شانس دارد Vanguard را به شما بدهد و باعث شود Avenger's Shield بعدی‌تان یک صاعقهٔ نور طنین‌انداز در خط بین شما و هدف اولیه بر جای بگذارد؛ این صاعقه دشمنان را با حداکثر 150% آسیب اولیهٔ واردشده سوراخ می‌کند.\n\nآسیب علیه اهداف ثانویه کاهش می‌یابد."
WoWFA_Data[1267211] = "Judgment 10% آسیب بیشتری وارد می‌کند. وقتی Vanguard را مصرف می‌کنید، 1 Holy Power به‌دست می‌آورید."
WoWFA_En[1267215] = "Your next cast of Shield of the Righteous after Vanguard deals $1269179s1% additional damage to your primary target and causes light to refract onto $s1 other $Ltarget:targets; for $1269224s1 Holy damage.\n\nDuring Avenging Wrath your Avenger's Shield always benefits from Vanguard."
WoWFA_Data[1267215] = "کست بعدی Shield of the Righteous شما پس از Vanguard، به هدف اصلی‌تان 100% آسیب اضافی وارد می‌کند و باعث می‌شود نور برای وارد کردن $1269224s1 آسیب Holy به 4 هدف دیگر منحرف شود.\n\nدر طول Avenging Wrath، Avenger's Shield شما همیشه از Vanguard بهره می‌برد."
WoWFA_Data[1270916] = "هزینه Mana مربوط به Holy Light به‌اندازه 10% و زمان کست آن به‌اندازه 15% کاهش می‌یابد."
WoWFA_Data[1271016] = "وقتی Avenging Wrath فعال نیست، 5% Mastery به‌دست می‌آورید.\n\nوقتی Avenging Wrath فعال است، 30% سرعت حرکت به‌دست می‌آورید."
WoWFA_Data[1271077] = "شفای Holy Light به‌اندازه 30% افزایش می‌یابد، اما هزینه Mana آن 20% بیشتر می‌شود."
WoWFA_Data[1271221] = "Light of Dawn به‌اندازه 20% بهره بیشتری از Mastery: Lightbringer دریافت می‌کند."
WoWFA_En[1271387] = "After casting a Holy Armament, your next $s1 $Lcast:casts; of $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?a137029[Holy Shock or Crusader Strike][Crusader Strike] bestow a Lesser Armament of the same kind on a nearby ally."
WoWFA_Data[1271387] = "پس از کست کردن یک Holy Armament، 3 کست بعدی $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?a137029[Holy Shock یا Crusader Strike][Crusader Strike] شما یک Lesser Armament از همان نوع به یک متحد نزدیک می‌بخشد."
WoWFA_En[1271466] = "When your Holy Bulwark absorbs damage or your Sacred Weapon deals damage or healing, you have a chance to gain $?c2[Grand Crusader][Awakening]."
WoWFA_Data[1271466] = "وقتی Holy Bulwark شما آسیب جذب می‌کند یا Sacred Weapon شما آسیب وارد می‌کند یا شفا می‌دهد، شانس دارید $?c2[Grand Crusader][Awakening] را به‌دست آورید."
WoWFA_En[1271553] = "$?c1[Holy Armaments activate][Divine Toll activates] Hammer and Anvil at $s1% effectiveness."
WoWFA_Data[1271553] = "$?c1[Holy Armaments][Divine Toll]، Hammer and Anvil را با اثربخشی 100% فعال می‌کند."
WoWFA_Data[1276945] = "Shield of the Righteous آسیب جادویی دریافتی را 12% کاهش می‌دهد."
WoWFA_En[1277005] = "$@spelldesc1277038"
WoWFA_Data[1277005] = "Judgment causes its primary target's successful melee attacks against you to grant a Physical absorb shield for 20% of the damage dealt. Limit $i."
WoWFA_Data[1277162] = "Shield of the Righteous تا 2 Holy Power بیشتر مصرف می‌کند و به‌ازای هر Holy Power اضافی مصرف‌شده، 50% آسیب بیشتری وارد می‌کند."
WoWFA_Data[1277443] = "هنگام در دست داشتن سپر، 15% شانس دارید اسپل‌های دریافتی را بلاک کنید و آسیب آن‌ها را 20% کاهش دهید. \n\nبدون سپر، 15% شانس دارید حملات نزدیک دریافتی را پَری کنید و آسیب آن‌ها را 20% کاهش دهید."
WoWFA_Data[1277651] = "شفای شما بر اساس میانگین درصد سلامتی متحدان دارای Beacon of Light شما، تا 10% افزایش می‌یابد."
WoWFA_En[1289728] = "$@spelldesc432472"
WoWFA_Data[1289728] = "Will the Light to coalesce and become manifest as a Holy Armament, wielded by your target.\n\n Sacred Weapon: \n\nWhile wielding a Sacred Weapon, your spells and abilities have a chance to deal $432616s1 additional Holy damage or healing to nearby targets. Effect is increased when Sacred Weapon strikes a single target, and reduced above 5. Lasts 20 ثانیه.\n\nBecomes Holy Bulwark after use.$?c1[\n\n|cFFFFFFFFGenerates 3 Holy Power.][]"
WoWFA_Data[1301732] = "Word of Glory دیگر نمی‌تواند Critical Strike بزند، اما شفای آن به‌اندازهٔ شانس Critical Strike شما افزایش می‌یابد و 80% از شفای بیش‌ازحد آن در عوض هدفش را در Light می‌پوشاند و یک سپر جذب آسیب به او می‌دهد."
